#include <stdio.h>
#include <stdbool.h>

int countPrimeSetBits(int left, int right) {
    bool prime[30] = {false};
    prime[2]=prime[3]=prime[5]=prime[7]=prime[11]=prime[13]=prime[17]=prime[19]=prime[23]=prime[29]=true;
    int ans = 0;
    for (int value = left; value <= right; ++value) {
        int x = value, bits = 0;
        while (x) { x &= x - 1; ++bits; }
        if (prime[bits]) ++ans;
    }
    return ans;
}

