class Solution {
public:
    int countPrimeSetBits(int left, int right) {
        bool prime[30];
        fill(begin(prime), end(prime), true);
        prime[0] = prime[1] = false;
        for (int i = 2; i * i < 30; ++i) if (prime[i])
            for (int j = i * i; j < 30; j += i) prime[j] = false;
        int ans = 0;
        for (int value = left; value <= right; ++value) {
            int x = value, bits = 0;
            while (x) { x &= x - 1; ++bits; }
            if (prime[bits]) ++ans;
        }
        return ans;
    }
};

code.Java:
class Solution {
    public int countPrimeSetBits(int left, int right) {
        boolean[] prime = new boolean[30];
        Arrays.fill(prime, true);
        prime[0] = prime[1] = false;
        for (int i = 2; i * i < prime.length; i++) {
            if (prime[i]) for (int j = i * i; j < prime.length; j += i) prime[j] = false;
        }
        int ans = 0;
        for (int value = left; value <= right; value++) {
            int x = value, bits = 0;
            while (x != 0) { x &= x - 1; bits++; }
            if (prime[bits]) ans++;
        }
        return ans;
    }
}

